-static Schema *_RdbLoadSchema
-(
-	RedisModuleIO *rdb,
-	GraphContext *gc,
-	SchemaType type,
-	bool already_loaded
-) {
-	/* Format:
-	 * id
-	 * name
-	 * #indices
-	 * index type
-	 * index data */
-
-	Schema *s = NULL ;
-	int id = RedisModule_LoadUnsigned (rdb) ;
-	char *name = RedisModule_LoadStringBuffer (rdb, NULL) ;
-	if (!already_loaded) {
-		bool created = false ;
-		s = GraphContext_FindOrAddSchema (gc, name, type, &created) ;
-		ASSERT (s != NULL) ;
-		ASSERT (created == true) ;
-		ASSERT (Schema_GetID (s) == id) ;
-	}
-
-	RedisModule_Free(name);
-
-	uint index_count = RedisModule_LoadUnsigned (rdb) ;
-	for (uint index = 0; index < index_count; index++) {
-		IndexType index_type = RedisModule_LoadUnsigned(rdb);
-
-		switch(index_type) {
-			case IDX_FULLTEXT:
-				_RdbLoadFullTextIndex(rdb, gc, s, already_loaded);
-				break;
-			case IDX_EXACT_MATCH:
-				_RdbLoadExactMatchIndex(rdb, gc, s, already_loaded);
-				break;
-			default:
-				ASSERT(false);
-				break;
-		}
-	}
-
-	return s ;
-}
