+	switch(encver) {
+		case 14:
+		case 15:
+		case 16:
+			return SerializerIO_FromRedisModuleIO (rdb, false) ;
+		case 17:
+		case 18:
+			return SerializerIO_FromBufferedRedisModuleIO (rdb, false) ;
+		case 19:
