-		// flush batches
-		//----------------------------------------------------------------------
-
-		// flush batch when:
-		// 1. batch is full
-		// 2. relation id changed
-		if(relation_changed ||
-		   (idx > 0 && idx >= BATCH_SIZE) ||
-		   (tensor_idx > 0 && tensor_idx >= BATCH_SIZE)) {
