-				ids, idx, false) ;
-	}
-
-	// flush last multi-edge batch
-	if(tensor_idx > 0) {
-		// flush batch
-		Serializer_OptimizedFormConnections (g, prev_relation,
-				tensor_srcs, tensor_dests, tensor_ids, tensor_idx, true) ;
