-static void _RdbLoadSchema
-(
-	RedisModuleIO *rdb,
-	GraphContext *gc,
-	SchemaType type,
-	bool already_loaded
-) {
-	/* Format:
-	 * id
-	 * name
-	 * #indices
-	 * (index type, indexed property) X M 
-	 * #constraints 
-	 * (constraint type, constraint fields) X N
-	 */
-
-	Schema *s    = NULL;
-	int     id   = RedisModule_LoadUnsigned(rdb);
