-			default:
-				ASSERT(false);
-				break;
-		}
-	}
-
-	//--------------------------------------------------------------------------
-	// load constraints
-	//--------------------------------------------------------------------------
-
-	_RdbLoadConstaints(rdb, gc, s, already_loaded);
-}
