+        "OMP_THREAD_COUNT" => positive.map(LoadArg::OmpThreadCount),
+        "NODE_CREATION_BUFFER" => non_negative.map(LoadArg::NodeCreationBuffer),
+        "INDEX_WORKER_THREADS" => non_negative.map(LoadArg::IndexWorkerThreads),
