+        assert_input_invariants(&input);
+        let cch = Cch::build(&input).expect("build");
+        assert_eq!(cch.node_count(), edges.n);
+        check_metric(&cch, edges, &input);
+        check_no_shortcut_beats_reality(&cch, edges);
+    }
