+/// A star: node `0` is the hub, `leaves` outer nodes, edges both ways with
+/// weight `w`.
+#[must_use]
+pub fn star(
+    leaves: u32,
+    w: f64,
+) -> EdgeList {
+    assert!(leaves >= 1);
+    let n = (leaves + 1) as usize;
+    let mut g = EdgeList::new(n);
+    for leaf in 1..=leaves {
+        g.push(0, leaf, w);
+        g.push(leaf, 0, w);
+    }
+    g
+}
