+
+    /// One conjunct, written out node by node in pre-order: `a.p = 1` is
+    /// `= property(p) a 1`.
+    fn render(expr: &DynTree<ExprIR<Variable>>) -> String {
+        expr.root()
+            .indices::<Dfs>()
+            .map(|idx| expr.node(idx).data().to_string())
+            .collect::<Vec<_>>()
+            .join(" ")
+    }
